/* @lc app=leetcode id=3998 lang=kotlin */ class Solution { fun transformStr(s: String, strs: Array<String>): BooleanArray = s.count { it == '1' }.let { c -> s.runningFold(0) { a, ch -> a + (ch - '0') }.let { ps -> strs.map { t -> (c - t.count { it == '1' }).let { need -> need in 0..t.count { it == '?' } && t.indices.filter { t[it] == '?' }.takeLast(need).toSet().let { st -> t.indices.runningFold(0) { a, i -> a + (if (t[i] == '1' || i in st) 1 else 0) }.drop(1).withIndex().all { (i, v) -> v <= ps[i + 1] } } } }.toBooleanArray() } } }